import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Karte","description":"Einträge als Markierungen auf einer Landkarte darstellen.","frontmatter":{"title":"Karte","description":"Einträge als Markierungen auf einer Landkarte darstellen."},"headers":[],"relativePath":"ansichten/karte.md","filePath":"ansichten/karte.md","lastUpdated":1786093505000}'),a={name:"ansichten/karte.md"};function s(l,e,o,d,u,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="karte" tabindex="-1">Karte <a class="header-anchor" href="#karte" aria-label="Permalink to &quot;Karte&quot;">​</a></h1><p>Die <strong>Karte</strong> zeigt Einträge als Markierungen auf einer Landkarte.</p><p>Die Oberfläche beschreibt sie als <em>Standorte auf einen Blick</em>.</p><p><strong>Geeignet für:</strong> Filialen, Kunden, Einsatzorte, Objekte, Veranstaltungsorte, Außendienstplanung.</p><h2 id="voraussetzung-ein-ortsfeld" tabindex="-1">Voraussetzung: ein Ortsfeld <a class="header-anchor" href="#voraussetzung-ein-ortsfeld" aria-label="Permalink to &quot;Voraussetzung: ein Ortsfeld&quot;">​</a></h2><p>Die Position der Markierungen kommt aus einem Feld vom Typ <strong>Geolokalisierung</strong> oder <strong>Adresse</strong>.</p><p>Der Hinweis in der Oberfläche nennt nur den ersten Typ:</p><blockquote><p><em>Um eine Karte zu sehen, muss Ihr Grid eine Spalte des Typs Geolokalisierung haben. Sie bestimmt die Position der Marker auf der Karte.</em></p></blockquote><p>Tatsächlich stehen beide Typen zur Auswahl.</p><div class="warning custom-block"><p class="custom-block-title">Adressen brauchen Koordinaten</p><p>Eine Adresse ist zunächst nur Text. Damit daraus eine Kartenmarkierung wird, müssen Koordinaten dazu ermittelt werden — die sogenannte Geokodierung.</p><p>Diese Funktion ist <strong>tarifabhängig</strong>: <em>Upgraden Sie auf Pro, um Kartenpins und Geolokalisierung für Adressen zu nutzen.</em></p><p>Bei Feldern vom Typ <strong>Geolokalisierung</strong> entfällt diese Einschränkung, weil die Koordinaten direkt im Feld stehen.</p></div><div class="tip custom-block"><p class="custom-block-title">Wenn Geokodierung nicht verfügbar ist</p><p>Legen Sie zusätzlich zur Adresse eine Spalte vom Typ <strong>Geolokalisierung</strong> an und tragen Sie die Koordinaten im Format <code>50.12,6.543</code> ein. Sie lassen sich aus jedem Kartendienst kopieren. Etwas Handarbeit, aber ohne Tarifbindung.</p></div><h2 id="karte-anlegen" tabindex="-1">Karte anlegen <a class="header-anchor" href="#karte-anlegen" aria-label="Permalink to &quot;Karte anlegen&quot;">​</a></h2><ol><li>Wählen Sie unter dem Grid <strong>Ansicht erstellen</strong>.</li><li>Wählen Sie <strong>Karte</strong>.</li><li>Legen Sie unter <strong>Einstellungen</strong> das Ortsfeld fest.</li></ol><p>Der Dialog heißt <em>Wählen Sie ein Feld des Typs Geolokalisierung</em> mit dem Hinweis <em>Das Feld bestimmt die Position der Marker auf der Karte.</em></p><p>Fehlt ein passendes Feld, bietet ApptiveGrid <strong>Erstellen Sie ein Feld</strong> an.</p><h2 id="in-der-karte-arbeiten" tabindex="-1">In der Karte arbeiten <a class="header-anchor" href="#in-der-karte-arbeiten" aria-label="Permalink to &quot;In der Karte arbeiten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Markierung</strong></td><td>Ein Eintrag. Ein Klick öffnet die Details.</td></tr><tr><td><strong>Hier suchen</strong></td><td>Sucht im aktuell sichtbaren Kartenausschnitt</td></tr><tr><td><strong>Einträge</strong></td><td>Liste der Einträge zur Karte</td></tr></tbody></table><p>Sind keine Einträge sichtbar, meldet die Ansicht <em>Keine Einträge auf der Karte</em>.</p><div class="tip custom-block"><p class="custom-block-title">„Keine Einträge auf der Karte&quot; hat drei Ursachen</p><ol><li>Das Ortsfeld ist bei den Einträgen leer.</li><li>Bei Adressen fehlt die Geokodierung, weil der Tarif sie nicht enthält.</li><li>Ein Filter der Ansicht blendet alles aus.</li></ol><p>Prüfen Sie das in dieser Reihenfolge. Ein Filter <code>Standort</code> <code>ist leer</code> in einer Tabellenansicht zeigt schnell, wie viele Einträge überhaupt eine Position haben.</p></div><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><p>Filter wirken wie in jeder Ansicht — sinnvoll, um die Karte auf einen Bereich einzugrenzen.</p><div class="tip custom-block"><p class="custom-block-title">Karten nach Zweck trennen</p><p>Statt aller Standorte auf einer Karte lohnen sich mehrere Ansichten: „Aktive Kunden&quot;, „Offene Einsätze&quot;, „Region Nord&quot;. Bei vielen Markierungen wird eine ungefilterte Karte schnell unleserlich.</p></div><p>→ <a href="/docs/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></li><li><a href="/docs/referenz/spaltentypen">Spaltentypen-Referenz</a> — Adresse und Geolokalisierung im Detail</li><li><a href="/docs/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></li></ul>',25)])])}const p=t(a,[["render",s]]);export{g as __pageData,p as default};
